{
  "name": "安全缓冲区访问组件",
  "name_en": "Safe Buffer Access Component",
  "manufacturer": "",
  "description": "一种非物理软件组件，用于在线程安全条件下读写与 PLC/Modbus 相关的输入、输出和内存缓冲区。它支持布尔、字节、16/32/64 位整数、批量读写、变量调试访问以及配置读取，常用于实验自动化程序中的共享数据交换与控制逻辑集成。",
  "description_en": "A non-physical software component for thread-safe reading and writing of PLC/Modbus-related input, output, and memory buffers. It supports boolean, byte, 16/32/64-bit integers, batch operations, variable inspection, and configuration access, and is commonly used for shared data exchange and control-logic integration in laboratory automation software.",
  "tag_hints": [
    "thread-safe buffer access",
    "PLC I/O buffers",
    "Modbus shared memory",
    "batch variable read/write",
    "mutex synchronization",
    "automation data exchange"
  ],
  "actions": [
    {
      "action_name": "auto-acquire_mutex",
      "description": "获取缓冲区互斥锁。",
      "description_en": "Acquire the buffer mutex."
    },
    {
      "action_name": "auto-batch_mixed_operations",
      "description": "批量执行混合读写操作。",
      "description_en": "Process mixed read and write operations in batch."
    },
    {
      "action_name": "auto-batch_read_values",
      "description": "批量执行多个读取操作。",
      "description_en": "Process multiple read operations in batch."
    },
    {
      "action_name": "auto-batch_write_values",
      "description": "批量执行多个写入操作。",
      "description_en": "Process multiple write operations in batch."
    },
    {
      "action_name": "auto-read_bool_input",
      "description": "读取布尔输入缓冲区值。",
      "description_en": "Read a boolean input buffer value."
    },
    {
      "action_name": "auto-read_bool_memory",
      "description": "读取布尔内存缓冲区值。",
      "description_en": "Read a boolean memory buffer value."
    },
    {
      "action_name": "auto-read_bool_output",
      "description": "读取布尔输出缓冲区值。",
      "description_en": "Read a boolean output buffer value."
    },
    {
      "action_name": "auto-read_byte_input",
      "description": "读取字节输入缓冲区值。",
      "description_en": "Read a byte input buffer value."
    },
    {
      "action_name": "auto-read_byte_output",
      "description": "读取字节输出缓冲区值。",
      "description_en": "Read a byte output buffer value."
    },
    {
      "action_name": "auto-read_dint_input",
      "description": "读取 32 位整数输入缓冲区值。",
      "description_en": "Read a 32-bit integer input buffer value."
    },
    {
      "action_name": "auto-read_dint_memory",
      "description": "读取 32 位整数内存缓冲区值。",
      "description_en": "Read a 32-bit integer memory buffer value."
    },
    {
      "action_name": "auto-read_dint_output",
      "description": "读取 32 位整数输出缓冲区值。",
      "description_en": "Read a 32-bit integer output buffer value."
    },
    {
      "action_name": "auto-read_int_input",
      "description": "读取 16 位整数输入缓冲区值。",
      "description_en": "Read a 16-bit integer input buffer value."
    },
    {
      "action_name": "auto-read_int_memory",
      "description": "读取 16 位整数内存缓冲区值。",
      "description_en": "Read a 16-bit integer memory buffer value."
    },
    {
      "action_name": "auto-read_int_output",
      "description": "读取 16 位整数输出缓冲区值。",
      "description_en": "Read a 16-bit integer output buffer value."
    },
    {
      "action_name": "auto-read_lint_input",
      "description": "读取 64 位整数输入缓冲区值。",
      "description_en": "Read a 64-bit integer input buffer value."
    },
    {
      "action_name": "auto-read_lint_memory",
      "description": "读取 64 位整数内存缓冲区值。",
      "description_en": "Read a 64-bit integer memory buffer value."
    },
    {
      "action_name": "auto-read_lint_output",
      "description": "读取 64 位整数输出缓冲区值。",
      "description_en": "Read a 64-bit integer output buffer value."
    },
    {
      "action_name": "auto-release_mutex",
      "description": "释放缓冲区互斥锁。",
      "description_en": "Release the buffer mutex."
    },
    {
      "action_name": "auto-set_var_value",
      "description": "设置指定索引的变量值。",
      "description_en": "Set the variable value for the specified index."
    },
    {
      "action_name": "auto-set_var_values_batch",
      "description": "设置多个变量的值。",
      "description_en": "Set the values of multiple variables."
    },
    {
      "action_name": "auto-write_bool_input",
      "description": "写入布尔输入缓冲区值，通常供 Modbus 主站更新 PLC 输入。",
      "description_en": "Write a boolean input buffer value, typically for a Modbus master to update PLC inputs."
    },
    {
      "action_name": "auto-write_bool_memory",
      "description": "写入布尔内存缓冲区值。",
      "description_en": "Write a boolean memory buffer value."
    },
    {
      "action_name": "auto-write_bool_output",
      "description": "写入布尔输出缓冲区值。",
      "description_en": "Write a boolean output buffer value."
    },
    {
      "action_name": "auto-write_byte_input",
      "description": "写入字节输入缓冲区值，通常供 Modbus 主站更新 PLC 输入。",
      "description_en": "Write a byte input buffer value, typically for a Modbus master to update PLC inputs."
    },
    {
      "action_name": "auto-write_byte_output",
      "description": "写入字节输出缓冲区值。",
      "description_en": "Write a byte output buffer value."
    },
    {
      "action_name": "auto-write_dint_input",
      "description": "写入 32 位整数输入缓冲区值，通常供 Modbus 主站更新 PLC 输入。",
      "description_en": "Write a 32-bit integer input buffer value, typically for a Modbus master to update PLC inputs."
    },
    {
      "action_name": "auto-write_dint_memory",
      "description": "写入 32 位整数内存缓冲区值。",
      "description_en": "Write a 32-bit integer memory buffer value."
    },
    {
      "action_name": "auto-write_dint_output",
      "description": "写入 32 位整数输出缓冲区值。",
      "description_en": "Write a 32-bit integer output buffer value."
    },
    {
      "action_name": "auto-write_int_input",
      "description": "写入 16 位整数输入缓冲区值，通常供 Modbus 主站更新 PLC 输入。",
      "description_en": "Write a 16-bit integer input buffer value, typically for a Modbus master to update PLC inputs."
    },
    {
      "action_name": "auto-write_int_memory",
      "description": "写入 16 位整数内存缓冲区值。",
      "description_en": "Write a 16-bit integer memory buffer value."
    },
    {
      "action_name": "auto-write_int_output",
      "description": "写入 16 位整数输出缓冲区值。",
      "description_en": "Write a 16-bit integer output buffer value."
    },
    {
      "action_name": "auto-write_lint_input",
      "description": "写入 64 位整数输入缓冲区值，通常供 Modbus 主站更新 PLC 输入。",
      "description_en": "Write a 64-bit integer input buffer value, typically for a Modbus master to update PLC inputs."
    },
    {
      "action_name": "auto-write_lint_memory",
      "description": "写入 64 位整数内存缓冲区值。",
      "description_en": "Write a 64-bit integer memory buffer value."
    },
    {
      "action_name": "auto-write_lint_output",
      "description": "写入 64 位整数输出缓冲区值。",
      "description_en": "Write a 64-bit integer output buffer value."
    },
    {
      "action_name": "auto-is_valid",
      "description": "获取实例是否已正确初始化。",
      "description_en": "Get whether the instance is properly initialized."
    },
    {
      "action_name": "auto-error_msg",
      "description": "获取初始化失败时的错误消息。",
      "description_en": "Get the error message if initialization failed."
    },
    {
      "action_name": "auto-get_var_list",
      "description": "获取指定索引的变量地址列表。",
      "description_en": "Get variable addresses for the specified indexes."
    },
    {
      "action_name": "auto-get_var_size",
      "description": "获取变量大小。",
      "description_en": "Get the variable size."
    },
    {
      "action_name": "auto-get_var_value",
      "description": "获取指定索引的变量值。",
      "description_en": "Get the variable value for the specified index."
    },
    {
      "action_name": "auto-get_var_count",
      "description": "获取变量总数。",
      "description_en": "Get the total variable count."
    },
    {
      "action_name": "auto-get_var_info",
      "description": "获取变量信息。",
      "description_en": "Get variable information."
    },
    {
      "action_name": "auto-get_var_sizes_batch",
      "description": "获取多个变量的大小。",
      "description_en": "Get sizes for multiple variables."
    },
    {
      "action_name": "auto-get_var_values_batch",
      "description": "获取多个变量的值。",
      "description_en": "Get values for multiple variables."
    },
    {
      "action_name": "auto-get_config_path",
      "description": "获取配置文件路径。",
      "description_en": "Get the configuration file path."
    },
    {
      "action_name": "auto-get_config_file_args_as_map",
      "description": "获取映射形式的配置文件参数。",
      "description_en": "Get configuration file arguments as a map."
    }
  ]
}

